def transform_candidate(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    processed=set()
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg: continue
            for dr,dc in ((1,1),(1,-1)):
                if (r,c,dr,dc) in processed: continue
                sr,sc=r,c
                while 0<=sr-dr<h and 0<=sc-dc<w and grid[sr-dr][sc-dc]==color:
                    sr-=dr; sc-=dc
                run=[]; rr,cc=sr,sc
                while 0<=rr<h and 0<=cc<w and grid[rr][cc]==color:
                    run.append((rr,cc)); processed.add((rr,cc,dr,dc))
                    rr+=dr; cc+=dc
                if len(run)<2: continue
                run_set=set(run)
                def outside_neighbors(pos):
                    pr,pc=pos
                    return sum(1 for ar in range(max(0,pr-1),min(h,pr+2))
                               for ac in range(max(0,pc-1),min(w,pc+2))
                               if grid[ar][ac]!=bg and (ar,ac) not in run_set)
                a,b=run[0],run[-1]
                na,nb=outside_neighbors(a),outside_neighbors(b)
                if na==nb: continue
                endpoint=a if na<nb else b
                inner=run[1] if endpoint==a else run[-2]
                step_r,step_c=endpoint[0]-inner[0],endpoint[1]-inner[1]
                rr,cc=endpoint[0]+step_r,endpoint[1]+step_c
                path=[]
                while 0<=rr<h and 0<=cc<w and grid[rr][cc]==bg:
                    path.append((rr,cc)); rr+=step_r; cc+=step_c
                if len(path)>=2:
                    for pr,pc in path: out[pr][pc]=color
    return out
